from pathlib import Path
import json,subprocess,datetime,hashlib
B=Path(__file__).parent;R='Apdelrahman1911/nativeCmpkit';N=71
review=json.loads((B.parent/'important-result-review.json').read_text());assert review['passed'] and review['finding']=='NATIVE-014' and len(review['original_acceptance'])==3 and all(c['accepted'] for c in review['original_acceptance'])
marker='<!-- nativecmpkit:direct-acceptance:NATIVE-014:c39d320c -->'
body='## Verified fix — close directly after important-test review\n\nAll **three original NATIVE-014 acceptance criteria** pass at immutable **c39d320c8f82d67e7671eb38cad19a4068f919aa**, [run40611192346](https://github.com/Apdelrahman1911/nativeCmpkit/actions/runs/40611192346): **8/8 real desktop cookie methods**, zero failures/errors/skips, including three new regression methods.\n\n- Delayed reads retain the exact original absolute expiry.\n- Copying a returned cookie to a second, independent real JDK store retains exactly the same expiry. Removing the source store does not alter the destination.\n- Session/null, already-past/epoch, a genuinely elapsed one-millisecond-past-second-boundary deadline, supported years0001–9999 and invalid/Long overflow timestamps pass. Invalid inputs fail before mutating an existing cookie.\n\nThe owning repair retains original expiry metadata by native-cookie identity instead of inventing `now + maxAge`; reads filter elapsed exact deadlines. Foreign-store metadata is explicitly unknown. Input validation precedes mutation. Public cookie shape/namespaces remain compatible; native Max-Age still has whole-second precision, which is not misrepresented as API metadata.\n\nReviewed source, **all741 exact own-Git input blobs**, unchanged before/after maps, every XML/artifact hash, fresh testcase identities, command and SDK/runtime correspondence. Important tests → review → **direct closure now** → archive/index afterward.\n\n**The whole workflow remains failed:39/40 executions,7 XML.** The independent JavaFX native-history test observed stale pageTitle (`A` instead of `C`); it does not use CookieManager and does not invalidate any cookie criterion. Its failure is retained and will be investigated, not hidden or called green. No unrelated successful suites were rerun.\n\nThis closure does **not** certify JavaFX authentication/global-cookie stores/native HTTP-header parity, other cookie/threading findings, physical/minimum devices, native sanitizers, ABI, dependency/legal/full consumers or release readiness. Those wider issues/gates remain open. No packages, releases or deployments published.\n\nEvidence: `docs/development/evidence/github-actions/40611192346/`. Original issue body/title/labels and historical failures preserved.\n\n<!-- nativecmpkit:direct-acceptance:NATIVE-014:c39d320c -->'

def api(path,step,method='GET',payload=None):
 target=B/(step+'.json');assert not target.exists()
 p=subprocess.run(['gh','api','repos/'+R+'/'+path,'--method',method]+([] if payload is None else ['--input','-']),input=None if payload is None else json.dumps(payload).encode(),capture_output=True,timeout=90);target.write_bytes(p.stdout)
 if p.returncode:
  raise RuntimeError('Uncertain request result: inspect stored response and reconcile read-only before any repeat mutation')
 return json.loads(p.stdout)
before=api(f'issues/{N}','issue-before');assert before['state']=='open' and 'NATIVE-014' in before['title'] and 'pull_request' not in before
comments=api(f'issues/{N}/comments?per_page=100','comments-before');assert len(comments)<100 and not any(marker in c['body'] for c in comments)
(B/'comment.md').write_text(body+'\n')
c=api(f'issues/{N}/comments','comment-response','POST',{'body':body});read=api(f'issues/comments/{c["id"]}','comment-readback');assert read['body']==body
api(f'issues/{N}','close-response','PATCH',{'state':'closed','state_reason':'completed'})
after=api(f'issues/{N}','issue-after');assert after['state']=='closed' and after['state_reason']=='completed' and after['closed_at']
for field in ('title','body','labels'):assert before[field]==after[field],field
closed=api('issues?state=closed&sort=updated&direction=desc&per_page=100','closed-list');assert len(closed)<100;count=len([i for i in closed if 'pull_request' not in i]);assert any(i['number']==N for i in closed)
result={'verified_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'passed':True,'issue':N,'finding':'NATIVE-014','state':'closed','state_reason':'completed','issue_url':after['html_url'],'comment_url':read['html_url'],'original_body_title_labels_preserved':True,'important_review_sha256':hashlib.sha256((B.parent/'important-result-review.json').read_bytes()).hexdigest(),'original_criteria_accepted':3,'POST_invocations':1,'PATCH_invocations':1,'direct_closure_before_repo_documentation':True,'total_closed_issues':count,'new_closures':1,'source_revision':review['source_revision'],'run_id':review['run_id'],'packages_releases_deployments_published':False}
(B/'closure-readback.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
